package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void defaultConstructorTest() {
        CommentsConfiguration comments = new CommentsConfiguration();
        assertNotNull(comments);
    }

    @Test
    public void constructorWithCommentsTest() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path1", Arrays.asList("comment1"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);
        assertEquals(comments, commentsConfig.getAllComments());
    }

    @Test
    public void setCommentForExistingPathTest() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path1", Collections.singletonList("comment1"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);

        String path = "path1";
        String[] commentLines = {"newComment"};
        commentsConfig.setComment(path, commentLines);
        assertEquals(Arrays.asList("newComment"), comments.get(path));
    }

    @Test
    public void setCommentForNonExistingPathTest() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);

        String path = "path2";
        String[] commentLines = {"newComment"};
        commentsConfig.setComment(path, commentLines);
        assertEquals(Collections.singletonList("newComment"), comments.get(path));
    }

    @Test
    public void setMultipleCommentsForPathTest() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);

        String path = "path1";
        String[] commentLines = {"comment1", "newComment"};
        commentsConfig.setComment(path, commentLines);
        assertEquals(Arrays.asList("comment1", "newComment"), comments.get(path));
    }

    @Test
    public void setSingleNewLineCommentForPathTest() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration commentsConfig = new CommentsConfiguration(comments);

        String path = "path2";
        String[] commentLines = {"\n"};
        commentsConfig.setComment(path, commentLines);
        assertEquals(Collections.singletonList("\n"), comments.get(path));
    }

    @Test
    public void getAllCommentsTest() {
        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("path1", Arrays.asList("comment1"));
        CommentsConfiguration commentsConfig = new CommentsConfiguration(expectedComments);

        assertEquals(expectedComments, commentsConfig.getAllComments());
    }
}
